INSERT INTO `email_templates` (`id`, `key`, `name`, `subject`, `body`, `available_variables`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'enquiry.received', 'Enquiry acknowledgement', 'We have your enquiry about {{ property_title }}', '<p>Dear {{ first_name }},</p><p>Verified.</p>', '[\"first_name\",\"property_title\",\"property_url\",\"reference_code\",\"agent_name\",\"site_name\"]', 1, '2026-08-04 10:09:30', '2026-08-04 10:13:10'),
(2, 'enquiry.assigned', 'Enquiry assigned to agent', 'New enquiry: {{ property_title }}', '<p>{{ agent_name }},</p><p>{{ name }} has enquired about <strong>{{ property_title }}</strong>.</p><p>Phone: {{ phone }}<br>Email: {{ email }}</p><blockquote>{{ message }}</blockquote><p><a href=\"{{ url }}\">Open the lead</a></p>', '[\"agent_name\",\"name\",\"email\",\"phone\",\"property_title\",\"message\",\"url\"]', 1, '2026-08-04 10:09:30', '2026-08-04 10:09:30'),
(3, 'appointment.confirmed', 'Viewing confirmed', 'Your viewing on {{ date }} is confirmed', '<p>Dear {{ first_name }},</p><p>Your viewing of <strong>{{ property_title }}</strong> is confirmed for <strong>{{ date }} at {{ time }}</strong>.</p><p>{{ agent_name }} will meet you there. Please reply if anything changes.</p>', '[\"first_name\",\"property_title\",\"date\",\"time\",\"agent_name\"]', 1, '2026-08-04 10:09:30', '2026-08-04 10:09:30'),
(4, 'appointment.reminder', 'Viewing reminder', 'Tomorrow: {{ property_title }} at {{ time }}', '<p>Dear {{ first_name }},</p><p>A reminder that you are viewing <strong>{{ property_title }}</strong> tomorrow at {{ time }}.</p><p><a href=\"{{ property_url }}\">See the listing again</a></p>', '[\"first_name\",\"property_title\",\"property_url\",\"time\"]', 1, '2026-08-04 10:09:30', '2026-08-04 10:09:30'),
(5, 'newsletter.confirm', 'Newsletter confirmation', 'Confirm your subscription to {{ site_name }}', '<p>Hello,</p><p>Please confirm you would like to receive new listings and market notes from {{ site_name }}.</p><p><a href=\"{{ url }}\">Confirm subscription</a></p><p>If this was not you, ignore this message and nothing more will be sent.</p>', '[\"site_name\",\"url\"]', 1, '2026-08-04 10:09:30', '2026-08-04 10:09:30'),
(6, 'contact.received', 'Contact form acknowledgement', 'Thank you for contacting {{ site_name }}', '<p>Dear {{ name }},</p><p>We have your message and will reply shortly.</p><blockquote>{{ message }}</blockquote><p>— {{ site_name }}</p>', '[\"name\",\"message\",\"site_name\"]', 1, '2026-08-04 10:09:30', '2026-08-04 10:09:30');

