--
-- Table structure for table `property_nearby_places`
--

CREATE TABLE `property_nearby_places` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `property_id` bigint(20) UNSIGNED NOT NULL,
  `category` enum('school','hospital','metro','airport','mall','restaurant','park','bank','bus_stop','railway','other') NOT NULL DEFAULT 'other',
  `name` varchar(190) NOT NULL,
  `distance_km` decimal(6,2) DEFAULT NULL,
  `travel_minutes` smallint(5) UNSIGNED DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `sort_order` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

