INSERT INTO `reviews` (`id`, `reviewable_type`, `reviewable_id`, `user_id`, `author_name`, `author_email`, `author_avatar`, `title`, `body`, `rating`, `rating_breakdown`, `video_url`, `status`, `is_featured`, `created_at`, `updated_at`) VALUES
(1, 'App\\Models\\Property', 1, 5, 'Ananya Krishnan', 'customer@aurum.test', NULL, 'Worth every rupee', 'The finish quality is genuinely better than the show flat suggested, which is not something I expected to write. Possession was three weeks early.', 5, NULL, NULL, 'approved', 1, '2026-08-03 08:37:29', '2026-08-04 09:15:31'),
(2, 'App\\Models\\Property', 2, NULL, 'Rohit Malhotra', 'rohit.malhotra@example.test', NULL, 'Good building, difficult parking', 'No complaints about the apartment itself. The visitor parking is under-provisioned and that becomes obvious on weekends.', 4, NULL, NULL, 'rejected', 0, '2026-08-02 08:37:29', '2026-08-04 09:15:32'),
(3, 'App\\Models\\Property', 3, NULL, 'Sneha Iyer', 'sneha.iyer@example.test', NULL, 'Handover took a year longer than promised', 'The apartment is fine. The schedule was not. Budget for a year of rent beyond whatever date you are given.', 2, NULL, NULL, 'approved', 0, '2026-08-01 08:37:29', '2026-08-04 09:15:51'),
(4, 'App\\Models\\Property', 4, NULL, 'Vikram Sethi', 'vikram.sethi@example.test', NULL, 'Excellent light through the afternoon', 'West-facing living room, which I was warned about and now consider the best thing about the place.', 5, NULL, NULL, 'pending', 0, '2026-07-31 08:37:29', '2026-07-31 08:37:29'),
(5, 'App\\Models\\Property', 5, NULL, 'Meera Raghavan', 'meera.raghavan@example.test', NULL, 'Management is responsive', 'Two maintenance requests, both dealt with inside a day. That is rarer than it should be.', 5, NULL, NULL, 'pending', 0, '2026-07-29 08:37:29', '2026-07-29 08:37:29'),
(6, 'App\\Models\\Property', 1, NULL, 'Arjun Bhatia', 'arjun.bhatia@example.test', NULL, 'Solid, if unremarkable', 'Everything works. Nothing surprises. For the price in this locality that is a reasonable trade.', 4, NULL, NULL, 'approved', 0, '2026-07-23 08:37:29', '2026-07-23 08:37:29'),
(7, 'App\\Models\\Property', 2, NULL, 'Priya Deshmukh', 'priya.deshmukh@example.test', NULL, 'The clubhouse makes it', 'We use the pool and the reading room far more than we expected to. It changed how the family uses weekends.', 5, NULL, NULL, 'approved', 0, '2026-07-15 08:37:29', '2026-07-15 08:37:29'),
(8, 'App\\Models\\Property', 3, NULL, 'Karan Shah', 'karan.shah@example.test', NULL, 'Lifts are a bottleneck at 9am', 'Two lifts for eighteen floors. Otherwise a well-run building with good security.', 3, NULL, NULL, 'approved', 0, '2026-07-07 08:37:29', '2026-07-07 08:37:29'),
(9, 'App\\Models\\Property', 4, NULL, 'Nikhil Rao', 'nikhil.rao@example.test', NULL, 'BUY CHEAP WATCHES ONLINE', 'Visit our store for the best replica timepieces at unbeatable prices, worldwide shipping available now.', 5, NULL, NULL, 'rejected', 0, '2026-07-27 08:37:29', '2026-07-27 08:37:29'),
(10, 'App\\Models\\Property', 5, NULL, 'Tanvi Menon', 'tanvi.menon@example.test', NULL, 'Never lived here', 'Writing on behalf of a competitor. Terrible place, do not buy, the builder is a fraud and everyone knows it.', 1, NULL, NULL, 'rejected', 0, '2026-07-20 08:37:29', '2026-07-20 08:37:29');

