INSERT INTO `properties` (`id`, `title`, `slug`, `category_id`, `status`, `price`, `location`, `bedrooms`, `bathrooms`, `area`, `short_description`, `full_description`, `amenities`, `is_featured`, `is_published`, `rera_number`, `construction_status`, `availability_status`, `google_map_embed`, `pdf_brochure`, `floor_plans`, `meta_title`, `meta_description`, `meta_keywords`, `videos`, `three_sixty_tour_url`, `created_at`, `updated_at`, `in_slider`, `slider_image`, `area_unit`) VALUES
(1, 'The Obsidian Penthouse', 'the-obsidian-penthouse', 1, 'For Sale', 2450000.00, 'Beverly Hills, CA', 3, 4, 4200.00, 'An architecturally significant penthouse boasting panoramic skyline views, high-end marble details, and private infinity pool.', 'Located at the highest peak of Beverly Hills, The Obsidian Penthouse represents the pinnacle of modern luxury living. Featuring 24-foot ceilings, automated floor-to-ceiling glass walls, and a master bathroom lined entirely with book-matched Italian marble. The layout is optimized for entertaining, presenting a double-chef kitchen, private wine vault, and a 1,200 sq. ft. heated terrace featuring a personal infinity pool. Residents enjoy access to private concierge lobby, secure underground parking, and private elevator landing access.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Elevator\",\"Air Conditioning\",\"High Speed Wi-Fi\"]', 1, 1, '', 'Ready To Move', 'Available', '', NULL, NULL, NULL, NULL, NULL, NULL, '', '2026-08-04 08:28:22', '2026-09-07 12:57:44', 0, NULL, 'Sq. Ft.'),
(2, 'Villa Seraphina', 'villa-seraphina', 2, 'For Sale', 8900000.00, 'Malibu, CA', 5, 6, 7800.00, 'A modern coastal architectural masterpiece offering absolute privacy, ocean access, and smart home automation.', 'Nestled in the private gated bluff of Malibu, Villa Seraphina represents the ultimate beachfront sanctuary. Architecturally designed to merge indoor luxury with outdoor coastal beauty, the residence utilizes a geometric steel frame construction with massive glass panels. Featuring a state-of-the-art home theater, private wellness spa, wine room, and private steps leading directly to a secluded sandy cove. The landscaped grounds include an outdoor kitchen, fire pits, and a saltwater pool looking out onto the Pacific Ocean.', '[\"Swimming Pool\",\"Private Garden\",\"Covered Parking\",\"24/7 Security\",\"Club House\",\"Air Conditioning\",\"Fire Safety\"]', 1, 1, NULL, 'Ready To Move', 'Available', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04 08:28:22', '2026-08-04 08:28:22', 0, NULL, 'Sq. Ft.'),
(3, 'The Lumina Office Suite', 'the-lumina-office-suite', 5, 'For Rent', 12500.00, 'Downtown Los Angeles, CA', 0, 2, 3100.00, 'A premium corporate office suite in the heart of the business district, optimized for corporate headquarters.', 'Positioned on the 42nd floor of the prestigious Lumina Tower, this corporate office suite offers unmatched views of the Los Angeles skyline. Spanning 3,100 square feet, the open-concept layout includes 4 private executive offices, a glass-walled boardroom, a modern receptionist lobby, and a private kitchenette. Fully equipped with high-speed fiber internet and access to the building\'s executive meeting rooms and secure parking garage.', '[\"Covered Parking\",\"24/7 Security\",\"Elevator\",\"High Speed Wi-Fi\",\"Air Conditioning\",\"Fire Safety\"]', 0, 1, NULL, 'Ready To Move', 'Available', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04 08:28:22', '2026-08-04 08:28:22', 0, NULL, 'Sq. Ft.'),
(4, 'The Sovereign Estate', 'the-sovereign-estate', 2, 'For Sale', 14800000.00, 'Bel Air, CA', 6, 8, 11200.00, 'A masterpiece of modern luxury, boasting dramatic architectural lines, glass floor-to-ceiling facades, and a private sanctuary.', 'Suspended above the canyons of Bel Air, The Sovereign Estate represents the pinnacle of modern luxury. Featuring a massive 11,200 sq. ft. floor plan, this architectural work of art is framed in structural steel and triple-glazed automated glass panels. Designed for high-society entertaining, it features a 12-seat private cinema, a wellness spa, an indoor waterfall, a 2,000-bottle wine cellar, and an infinity pool that seamlessly merges with the skyline view.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 1, 1, 'RERA-90210-SE', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:07', '2026-08-06 11:16:07', 0, NULL, 'Sq. Ft.'),
(5, 'The Riviera Pavilion', 'the-riviera-pavilion', 2, 'For Sale', 18500000.00, 'Monte Carlo, Monaco', 5, 6, 8900.00, 'Overlooking the Mediterranean, this trophy estate offers tiered manicured gardens and private wellness spa.', 'Located on the exclusive Monaco cliffs, The Riviera Pavilion offers uninterrupted views of the yacht harbor. Features include white Italian marble flooring throughout, a private elevator connecting the beach dock to the master suite, high-end automated control systems, tiered gardens with olive trees, and private helicopter landing rights. A truly rare asset for UHNW buyers.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 1, 1, 'RERA-MON-RP', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:08', '2026-08-06 11:16:08', 0, NULL, 'Sq. Ft.'),
(6, 'Vortex Commercial Tower', 'vortex-commercial-tower', 4, 'For Rent', 45000.00, 'Manhattan, NY', 0, 10, 15400.00, 'Premium double-height retail and corporate headquarters space in midtown Manhattan.', 'A premier retail and corporate headquarters site in the heart of Manhattan. Spanning 15,400 sq. ft. over three levels, this workspace is equipped with state-of-the-art ventilation systems, high-speed elevators, 24/7 security desks, meeting halls, and private executive parking garage access. High foot-traffic frontage.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 0, 1, 'RERA-NYC-VT', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:08', '2026-08-06 11:16:08', 0, NULL, 'Sq. Ft.'),
(7, 'Aura Glass Penthouse', 'aura-glass-penthouse', 1, 'For Sale', 5200000.00, 'Miami Beach, FL', 3, 4, 4100.00, 'Fully automated smart penthouse featuring panoramic ocean views and private rooftop terrace.', 'Located on the golden sands of Miami Beach, Aura Glass Penthouse offers a lifestyle of sheer luxury. Boasting a private rooftop pool terrace, custom European cabinets, private elevator, automated blinds, and top-tier security. Perfect beachfront sanctuary with panoramic floor-to-ceiling glass wrapping around all rooms.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 1, 1, 'RERA-MIA-AGP', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:09', '2026-08-06 11:16:09', 0, NULL, 'Sq. Ft.'),
(8, 'Blackwood Forest Chalet', 'blackwood-forest-chalet', 3, 'For Sale', 3850000.00, 'Aspen, CO', 4, 5, 5800.00, 'A bespoke mountain sanctuary built with natural blackwood timber and local stone, complete with indoor fireplace.', 'This majestic ski-in/ski-out lodge combines traditional alpine charm with state-of-the-art modern comforts. Features include heated floors, stone-walled fireplaces, private sauna room, outdoor hot tub overlooking the slopes, large wine storage cellar, and automated lighting controls throughout. Custom-made for winter getaways.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 0, 1, 'RERA-CO-BFC', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:10', '2026-08-06 11:16:10', 0, NULL, 'Sq. Ft.'),
(9, 'The Zenith Workspace', 'the-zenith-workspace', 5, 'For Rent', 8500.00, 'London, UK', 0, 3, 2200.00, 'A state-of-the-art office suite in the financial district, featuring high-speed optical fiber connectivity.', 'Set on the 18th floor of London\'s premier financial tower, this corporate office suite is optimized for high-performing teams. Featuring private executive meeting rooms, a modern kitchenette, full soundproofing, central climate control, and high-security credentials.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 0, 1, 'RERA-LON-ZW', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:10', '2026-08-06 11:16:10', 0, NULL, 'Sq. Ft.'),
(10, 'Elysian Cove Retreat', 'elysian-cove-retreat', 2, 'For Sale', 22000000.00, 'Santorini, Greece', 4, 5, 6500.00, 'A breathtaking cliffside mansion offering panoramic Caldera sunset views and carved-cave pools.', 'Carved directly into the volcanic cliffs of Santorini, Elysian Cove represents the absolute pinnacle of Mediterranean architecture. Features include hand-hewn cave spas, infinity pool overlooking the Aegean Sea, custom marble floors, white dome vaults, and absolute panoramic privacy. Built to impress.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 1, 1, 'RERA-GR-ECR', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:11', '2026-08-06 11:16:11', 0, NULL, 'Sq. Ft.'),
(11, 'Apex Logistics Hub', 'apex-logistics-hub', 4, 'For Rent', 18000.00, 'Chicago, IL', 0, 4, 25000.00, 'Premium-grade logistics facility with advanced temperature control systems and high-ceiling loading bays.', 'A large 25,000 sq. ft. logistics and distribution facility in a prime Chicago zone. Equipped with advanced climate controls, multiple loading docks, high-strength concrete flooring, office support spaces, and secure automated perimeter fences.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 0, 1, 'RERA-CHI-ALH', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:12', '2026-08-06 11:16:12', 0, NULL, 'Sq. Ft.'),
(12, 'The Helix Residence', 'the-helix-residence', 3, 'For Sale', 6900000.00, 'Beverly Hills, CA', 5, 6, 8200.00, 'Clean minimalist design featuring floating staircases, infinity lap pool, and integrated solar.', 'A modern geometric home optimized for sustainable luxury living. Features include a floating architectural staircase, built-in outdoor theater deck, a saltwater lap pool, smart security systems, and integrated solar arrays with dual backup battery packs.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 0, 1, 'RERA-BH-THR', 'Ready To Move', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:12', '2026-08-06 11:16:12', 0, NULL, 'Sq. Ft.'),
(13, 'Aero Horizon Estate', 'aero-horizon-estate', 7, 'For Sale', 9500000.00, 'Palm Springs, CA', 0, 0, 87000.00, 'Premium estate land parcel with custom architectural plans and scenic desert mountain backdrops.', 'A breathtaking 87,000 sq. ft. pristine land parcel in a highly desirable Palm Springs neighborhood. Comes with pre-approved modern villa blueprints, water line access, perimeter security, and panoramic desert valley views. A perfect development opportunity.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"24\\/7 Security\",\"Air Conditioning\"]', 0, 1, 'RERA-PS-AHE', 'Under Construction', 'Available', NULL, NULL, '[]', NULL, NULL, NULL, '[]', NULL, '2026-08-06 11:16:13', '2026-08-06 11:16:13', 0, NULL, 'Sq. Ft.'),
(14, 'Luxury House', 'luxury-house', 3, 'For Sale', 2000000.00, 'Dehradun, Uttarakhand', 3, 3, 2500.00, 'Luxury House on Valley', 'Located at the highest peak of Beverly Hills, The Obsidian Penthouse represents the pinnacle of modern luxury living. Featuring 24-foot ceilings, automated floor-to-ceiling glass walls, and a master bathroom lined entirely with book-matched Italian marble. The layout is optimized for entertaining, presenting a double-chef kitchen, private wine vault, and a 1,200 sq. ft. heated terrace featuring a personal infinity pool. Residents enjoy access to private concierge lobby, secure underground parking, and private elevator landing access.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"Air Conditioning\"]', 0, 1, 'RERA-87896', 'Ready To Move', 'Available', '', NULL, NULL, '', '', '', NULL, '', '2026-08-19 11:15:00', '2026-08-19 11:15:00', 0, NULL, 'Sq. Ft.'),
(15, '5 BHK Luxury House In Doon Valley', '5-bhk-luxury-house-in-doon-valley', 3, 'For Sale', 25000000.00, 'Shastradhara Road, Dehradun', 5, 6, 3500.00, 'Luxury House on Valley', 'Located on the exclusive Monaco cliffs, The Riviera Pavilion offers uninterrupted views of the yacht harbor. Features include white Italian marble flooring throughout, a private elevator connecting the beach dock to the master suite, high-end automated control systems, tiered gardens with olive trees, and private helicopter landing rights. A truly rare asset for UHNW buyers', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"Elevator\"]', 0, 1, 'RERA-8765', 'Ready To Move', 'Available', '', NULL, NULL, '', '', '', NULL, '', '2026-08-19 11:45:13', '2026-08-19 11:45:13', 0, NULL, 'Sq. Ft.'),
(16, 'Beauty in Valley', 'beauty-in-valley', 3, 'For Sale', 2500000.00, 'Shastradhara Road, Dehradun', 4, 5, 3500.00, 'Luxury House on Valley', 'Nestled in the private gated bluff of Malibu, Villa Seraphina represents the ultimate beachfront sanctuary. Architecturally designed to merge indoor luxury with outdoor coastal beauty, the residence utilizes a geometric steel frame construction with massive glass panels. Featuring a state-of-the-art home theater, private wellness spa, wine room, and private steps leading directly to a secluded sandy cove. The landscaped grounds include an outdoor kitchen, fire pits, and a saltwater pool looking out onto the Pacific Ocean.', '[\"Swimming Pool\",\"Gymnasium\",\"Covered Parking\",\"Elevator\",\"High Speed Wi-Fi\",\"Club House\"]', 0, 1, 'RERA-87896', 'Ready To Move', 'Sold', '', NULL, NULL, 'beauty in valley', 'beauty-in-valley description', 'Description', '[{\"type\":\"youtube\",\"url\":\"https:\\/\\/www.youtube.com\\/watch?v=ZhiT5es1mnU\"}]', '', '2026-08-19 12:10:59', '2026-09-10 09:57:35', 0, NULL, 'Sq. Ft.');

